package dev.matchlab;import java.util.*;
public final class ReportFormatter {public String markdown(TelemetryAnalyzer.Report r){var b=new StringBuilder("# Telemetry summary\n\n");b.append("| Metric | Value |\n|---|---:|\n").append("| Samples | ").append(r.samples()).append(" |\n").append(String.format(Locale.ROOT,"| RMS path error | %.3f |%n| Motor imbalance | %.3f |%n| Reliability | %.1f%% |%n",r.rmsPathError(),r.motorImbalance(),100*r.reliability()));b.append("\n## Faults\n");if(r.faults().isEmpty())b.append("No configured thresholds were exceeded.\n");else r.faults().forEach(f->b.append("- **").append(f.rule()).append("**: ").append(f.explanation()).append('\n'));return b.toString();}}
